// ===========================================================================
//  SỔ ĐIỂM SỐNG - ghi lại mọi tín hiệu rồi đo kết quả THẬT sau N ngày.
//  Chạy mỗi ngày: ghi tín hiệu mới + chốt tín hiệu đã đến hạn. Gửi báo cáo thứ 6.
// ===========================================================================
const WATCHLIST = ['BID', 'VCB', 'MBB', 'STB', 'BCM', 'FPT', 'VNM', 'MWG', 'HPG', 'DGC', 'SSI', 'VND'];
const TEST_MODE = false;   // true = gửi báo cáo ngay (kể cả không phải thứ 6)
const HOLD_DAYS = 14;      // số NGÀY LỊCH giữ trước khi chốt đo kết quả
const DIP_PCT = 4;         // giảm >= % này 1 phiên -> tín hiệu DIP
const STREAK_MIN = 3;      // khối ngoại gom >= N phiên
const CHEAP_RATIO = 0.8;   // P/E <= 0.8 * P/E TB 5 năm -> rẻ so lịch sử
// ===========================================================================

const to = Math.floor(Date.now() / 1000);
const from = to - 60 * 60 * 24 * 120;
const todayStr = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' });
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const hBar = { 'User-Agent': UA, 'Accept': '*/*' };
const hFin = { 'User-Agent': UA, 'Accept': 'application/json', 'Referer': 'https://dstock.vndirect.com.vn/' };

const fetchBars = async (t) => {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://services.entrade.com.vn/chart-api/v2/ohlcs/stock', qs: { symbol: t, from, to, resolution: '1D' }, headers: hBar, json: true, timeout: 15000 });
    if (res && Array.isArray(res.c) && res.c.length) return res;
  } catch (e) { /* fallback */ }
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://dchart-api.vndirect.com.vn/dchart/history', qs: { symbol: t, resolution: 'D', from, to }, headers: { ...hBar, Referer: 'https://dchart.vndirect.com.vn/' }, json: true, timeout: 15000 });
    if (res && Array.isArray(res.c) && res.c.length) return res;
  } catch (e) { /* none */ }
  return null;
};

const fetchPE = async (t) => {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/ratios?q=code:' + t + '~itemCode:51006,1000043&sort=reportDate:desc&size=10', headers: hFin, json: false, timeout: 15000 });
    let p; try { p = typeof res === 'string' ? JSON.parse(res) : res; } catch (e) { p = null; }
    const m = {}; for (const d of ((p && p.data) || [])) { if (!(d.ratioCode in m)) m[d.ratioCode] = d.value; }
    return { pe: m['PRICE_TO_EARNINGS'], pe5: m['PRICE_TO_EARNINGS_AVG_CR_5Y'] };
  } catch (e) { return {}; }
};

const fetchFlow = async (t) => {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/foreigns?q=code:' + t + '&size=5&sort=tradingDate:desc', headers: hFin, json: true, timeout: 15000 });
    return ((res && res.data) || []).map(x => (x.netVal || 0) / 1e9);
  } catch (e) { return []; }
};

const sd = $getWorkflowStaticData('global');
sd.log = sd.log || [];
const log = sd.log;
const hasOpen = (t, setup) => log.some(r => r.ticker === t && r.setup === setup && !r.resolved);
const daysBetween = (a, b) => Math.round((new Date(b) - new Date(a)) / 86400000);

const debug = [];
for (const t of WATCHLIST) {
  try {
    const bars = await fetchBars(t);
    if (!bars || bars.c.length < 3) { debug.push(t + ': thiếu giá'); continue; }
    const n = bars.c.length;
    const close = bars.c[n - 1], prev = bars.c[n - 2];
    const pct = prev ? ((close - prev) / prev * 100) : 0;
    const dataDate = new Date(bars.t[n - 1] * 1000).toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' });

    // CHỐT các tín hiệu đã đến hạn (>= HOLD_DAYS) bằng giá hiện tại
    for (const r of log) {
      if (r.ticker === t && !r.resolved && daysBetween(r.date, todayStr) >= HOLD_DAYS) {
        r.ret = +(((close / r.entry) - 1) * 100).toFixed(2);
        r.resolved = true; r.exitDate = todayStr;
      }
    }

    // PHÁT HIỆN tín hiệu hôm nay
    const active = [];
    if (pct <= -DIP_PCT) active.push('DIP');
    const pe = await fetchPE(t);
    if (pe.pe > 0 && pe.pe5 > 0 && pe.pe <= CHEAP_RATIO * pe.pe5) active.push('CHEAP_HIST');
    const nets = await fetchFlow(t);
    if (nets.length >= STREAK_MIN && nets.slice(0, STREAK_MIN).every(x => x > 0)) active.push('KN_GOM');

    for (const setup of active) {
      if (!hasOpen(t, setup)) log.push({ date: dataDate, ticker: t, setup, entry: close, resolved: false });
    }
    debug.push(t + ': OK (pct ' + pct.toFixed(1) + '%, tín hiệu: ' + (active.join(',') || '-') + ')');
  } catch (e) {
    debug.push(t + ': ❌ ' + (e.message || String(e)));
  }
}

if (log.length > 1500) sd.log = log.slice(-1500);

// THỐNG KÊ các lệnh đã chốt
const SETUPS = [['DIP', '🎯 Giảm sâu (mean-reversion)'], ['CHEAP_HIST', '💎 Rẻ so lịch sử (P/E < 0.8× TB5N)'], ['KN_GOM', '📈 Khối ngoại gom ≥3 phiên']];
const stat = (setup) => {
  const rs = log.filter(r => r.setup === setup && r.resolved);
  if (!rs.length) return null;
  const win = rs.filter(r => r.ret > 0).length;
  const avg = rs.reduce((a, r) => a + r.ret, 0) / rs.length;
  let worst = rs[0].ret; for (const r of rs) if (r.ret < worst) worst = r.ret;
  return { n: rs.length, win: 100 * win / rs.length, avg, worst };
};
const openCount = log.filter(r => !r.resolved).length;
const resolvedCount = log.filter(r => r.resolved).length;

const now = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
let body = '📒 *SỔ ĐIỂM SỐNG* — hệ thống tự chấm\n_' + now + '_\n\n'
  + '_Tín hiệu THẬT đã phát ra, đo kết quả sau ' + HOLD_DAYS + ' ngày (không phải backtest):_\n\n';
for (const [code, label] of SETUPS) {
  const s = stat(code);
  body += '*' + label + '*\n' + (s
    ? '   ' + s.n + ' lệnh đã chốt · thắng ' + s.win.toFixed(0) + '% · TB ' + (s.avg >= 0 ? '+' : '') + s.avg.toFixed(1) + '% · tệ nhất ' + s.worst.toFixed(1) + '%'
    : '   _chưa có lệnh nào đến hạn chốt_') + '\n\n';
}
body += '⏳ Đang theo dõi (chưa đến hạn): *' + openCount + '* tín hiệu · đã chốt: ' + resolvedCount + '\n'
  + '\n_Vào lệnh giá đóng cửa khi tín hiệu xuất hiện · giữ ' + HOLD_DAYS + ' ngày · KHÔNG phải khuyến nghị_';

// Chỉ gửi báo cáo vào thứ 6 (hoặc TEST_MODE) - các ngày khác vẫn ghi/chốt thầm lặng
const weekday = new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Ho_Chi_Minh', weekday: 'short' });
const send = TEST_MODE || weekday === 'Fri';

return [{ json: { hasReport: send, message: body, debug, openCount, resolvedCount } }];
